	"golive__tip_broadcaster_2": "<b>TIP:</b> noem mensen die je live video bekijken bij naam, dat vinden ze fantastisch.",
	"golive__tip_broadcaster_3": "<b>TIP:</b> Maak je live video minimaal een paar minuten lang zodat mensen je eenvoudiger kunnen vinden.",
	"golive__tip_broadcaster_4": "<b>TIP:</b> vraag je kijkers waar ze vandaan komen om het ijs te breken.",
	"golive__tip_broadcaster_5": "<b>TIP:</b> Bedank mensen voor hun aanwezigheid en reageer op hun reacties om ze betrokken te houden bij je video.",
	"golive__tip_broadcaster_6": "<b>TIP:</b> Als je geen verbinding meer hebt tijdens je live video, ga dan ergens heen waar het bereik beter is.",
