	"golive__tip_broadcaster_8": "<b>TIP:</b> Begin je live video door meteen hallo te zeggen. Mensen die naderhand kijken zullen het zeker waarderen.",
	"golive__tip_broadcaster_9": "<b>TIP:</b> Bedank je kijkers voordat je je live video afsluit.",
	"golive__tip_pre_broadcast_1": "<b>TIP:</b> Maak een titel voor je live gaat om mensen te helpen je video te vinden.",
	"golive__tip_pre_broadcast_2": "<b>TIP:</b> Een beschrijvende titel zorgt ervoor dat mensen beter begrijpen waar je live video over gaat.",
	"golive__tip_pre_broadcast_3": "<b>TIP:</b> Ideeën nodig? Geef een tour, deel een talent of praat over een onderwerp dat je interessant vindt.",
	"golive__tip_pre_broadcast_4": "<b>TIP:</b> Zorg ervoor dat je telefoon een goede verbinding heeft voor je live gaat.",
	"golive__tip_pre_broadcast_5": "<b>TIP:</b> Voeg een hashtag toe aan je titel om mensen te helpen je video te vinden.",
