	"identity_education_conditions_age_verification": "Ik ga ermee akkoord dat X en Persona afbeeldingen van mijn ID en mijn foto gebruiken om mijn leeftijd te bevestigen. X en xAI slaan mogelijk je leeftijdsgegevens op. {{}}Meer informatie{{}}",
	"identity_education_conditions_eea": "Ik stem ermee in dat X afbeeldingen van mijn paspoort of identiteitsbewijs, inclusief biometrische gegevens, en persoonlijke gegevens van mijn profiel deelt met Au10tix om mijn identiteit te bevestigen. Ik geef X ook toestemming om mijn ID-afbeeldingen, inclusief biometrische gegevens, maximaal 30 dagen op te slaan en deze, en gegevens van mijn profiel, te gebruiken voor veiligheidsdoeleinden, waaronder het voorkomen van impersonatie. {{}}Meer informatie{{}}",
	"identity_education_conditions_persona_vendor": "Ik ga ermee akkoord dat X en Persona afbeeldingen van mijn ID en mijn selfie, inclusief geëxtraheerde biometrische gegevens, gebruiken om mijn identiteit te bevestigen, en voor aan X gerelateerde veiligheids-, beveiligings-, fraudepreventie- en betalingsdoeleinden. Persona mag dergelijke gegevens maximaal 30 dagen opslaan. X mag mijn volledige naam, adres en hashes van het ID-nummer van mijn document opslaan zolang ik geabonneerd op de X Premium-service. {{}}Meer informatie{{}}",
