	"payment_funds_insurance_footer_secondary_text": "Kijk ﻿hier﻿ voor meer informatie over FDIC-verzekeringen en categorieën van rekeninghouders.",
	"payment_funds_insurance_footer_text": "\"Je deposito's worden beheerd door Cross River Bank, lid van de FDIC, en zijn door de FDIC verzekerd tot een bedrag van $ 250.000 per persoon en per rechtspersoon voor alle rekeningen in elke categorie van rekeninghouders bij de bank (gecombineerd), inclusief rekeningen die in een vertegenwoordigende hoedanigheid worden aangehouden.\"",
	"payment_funds_insurance_footer_text_format": "\"Je deposito's worden beheerd door Cross River Bank ('de Bank'), lid van de FDIC, en zijn door de FDIC verzekerd tot een bedrag van {amount} per persoon en per rechtspersoon voor alle rekeningen in elke categorie van rekeninghouders bij de Bank (gecombineerd), inclusief rekeningen die in een vertegenwoordigende hoedanigheid worden aangehouden.\"",
	"payment_funds_insurance_sweep_disclaimer": "\"Deposito's worden aangehouden bij Cross River Bank, lid van de ﻿FDIC, en bij andere door de FDIC verzekerde instellingen﻿. ﻿Er moet aan bepaalde voorwaarden ﻿worden voldaan voordat de pass-through depositoverzekering van toepassing is. X Payments LLC is geen door de FDIC verzekerde bank. Een depositoverzekering dekt alleen het faillissement van een verzekerde bank.\"",
	"payment_funds_insurance_sweep_presentation": "\"Je deposito's worden automatisch ingeschreven in het cash sweep-programma van X, dat tot $ 10.000.000 aan totale FDIC-verzekering biedt, onder voorbehoud van bepaalde beperkingen. ﻿Meer informatie﻿.\"",
