	"profile_smart_blocked_autoblocked_by_twitter_description": "\"Je bent tijdelijk automatisch geblokkeerd voor het bekijken van en een interactie aangaan met de posts van @%1$s. Dit gebeurde terwijl de Veiligheidsmodus van de gebruiker was ingeschakeld en wij je interacties als potentieel beledigend of spammy hebben gemarkeerd.\n\nWe weten dat we gebruikers niet altijd terecht automatisch blokkeren, dus we werken hard om ons detectiesysteem te verbeteren.\n\n{{}}Wat%2$sis de %2$sVeiligheidsmodus?{{}}\n\nDit zijn manieren waarop je gezonde gesprekken blijft voeren en waarmee je voorkomt dat je automatisch wordt geblokkeerd.\"",
