	"ps__tip_broadcaster_11": "<b>TIP:</b> Bedankt dat je uitzendt op Periscope! ≺3",
	"ps__tip_broadcaster_2": "<b>TIP:</b> Noem kijkers die deelnemen bij naam, dat vinden ze fantastisch!",
	"ps__tip_broadcaster_3": "<b>TIP:</b> Maak je uitzending minimaal een paar minuten lang zodat mensen je eenvoudiger kunnen vinden.",
	"ps__tip_broadcaster_4": "<b>TIP:</b> Vraag je kijkers waar ze vandaan komen om het ijs te breken.",
	"ps__tip_broadcaster_5": "<b>TIP:</b> Bedank kijkers voor hun aanwezigheid en reageer op hun reacties om ze betrokken te houden bij je uitzending.",
	"ps__tip_broadcaster_6": "<b>TIP:</b> Als je geen verbinding meer hebt tijdens je uitzending, ga dan ergens heen waar het bereik beter is.",
	"ps__tip_broadcaster_7": "<b>TIP:</b> Vraag je kijkers om je te volgen zodat ze een melding krijgen wanneer je live gaat.",
	"ps__tip_broadcaster_8": "<b>TIP:</b> Begin je uitzending door meteen hallo te zeggen. Je herhalingskijkers zullen het zeker waarderen.",
	"ps__tip_broadcaster_9": "<b>TIP:</b> Bedank je kijkers voordat je je uitzending afsluit.",
	"ps__tip_pre_broadcast_1": "<b>TIP:</b> Maak een titel voor je uitzending begint en leer mensen met dezelfde interesses kennen!",
	"ps__tip_pre_broadcast_2": "<b>TIP:</b> Een beschrijvende titel zorgt ervoor dat mensen beter begrijpen waar je uitzending over gaat.",
	"ps__tip_pre_broadcast_3": "<b>TIP:</b> Ideeën nodig? Geef een tour, deel een talent of praat over een onderwerp dat je interessant vindt.",
	"ps__tip_pre_broadcast_4": "<b>TIP:</b> Zorg ervoor dat je telefoon een goede verbinding heeft voor je live gaat.",
	"ps__tip_pre_broadcast_5": "<b>TIP:</b> Deel je uitzendingen op Twitter om meer kijkers te bereiken.",
	"ps__tip_pre_broadcast_6": "<b>TIP:</b> Als je mensen volgt die jou ook volgen, kun je een privé-uitzending voor ze maken.",
	"ps__tip_pre_broadcast_8": "<b>TIP:</b> Voeg een relevante hashtag toe aan je titel om mensen te helpen je uitzending te vinden.",
	"ps__tip_pre_broadcast_9": "<b>TIP:</b> Dat waren al onze tips, bedankt dat je Periscope gebruikt!",
	"ps__tip_viewer_1": "<b>TIP:</b> Je bent de eerste die deelneemt, schrijf een reactie en zeg hallo!",
	"ps__tip_viewer_2": "<b>TIP:</b> Laat een reactie achter en laat <b>%1$s</b> weten dat je er bent!",
	"ps__tip_viewer_3": "<b>TIP:</b> Laat <b>%1$s</b> weten op welke locatie je kijkt!",
	"ps__tip_viewer_4": "<b>TIP:</b> Zeg hallo om te chatten met <b>%1$s</b> en andere kijkers.",
